{
  "focus_ref": "29:38",
  "trace_kind": "reconstructed",
  "baseline_models": [
    {
      "model_id": "B1",
      "reading": "ʿĀd and Thamūd are recalled through what their dwellings make evident. Satan made their deeds attractive to them and consequently diverted them from the way, although they possessed discernment.",
      "status": "supported",
      "focus_anchor": {
        "quote_ar": "وَعَادًۭا وَثَمُودَا۟ وَقَد تَّبَيَّنَ لَكُم مِّن مَّسَٰكِنِهِمْ ۖ وَزَيَّنَ لَهُمُ ٱلشَّيْطَٰنُ أَعْمَٰلَهُمْ فَصَدَّهُمْ عَنِ ٱلسَّبِيلِ وَكَانُوا۟ مُسْتَبْصِرِينَ",
        "role": "The whole ayah joins evident habitation, attractive deeds, diversion, and persisting perceptual capacity."
      },
      "activation_trace": [
        {
          "source_ref": "29:38",
          "root": "ع و د",
          "source_word_indices": ["1"],
          "mapped_root_id": "root_001058",
          "branch_id": "B012",
          "variant_id": "V001",
          "role": "The proper-name scope supports reading ʿĀd as the named people, not as repetition or return."
        },
        {
          "source_ref": "29:38",
          "root": "ب ي ن",
          "source_word_indices": ["4"],
          "mapped_root_id": "root_000170",
          "branch_id": "B004",
          "variant_id": "V001",
          "role": "Becoming apparent supports evidence made clear from the dwellings."
        },
        {
          "source_ref": "29:38",
          "root": "س ك ن",
          "source_word_indices": ["7"],
          "mapped_root_id": "root_000726",
          "branch_id": "B002",
          "variant_id": "V001",
          "role": "The habitation scope identifies the dwellings as concrete residences."
        },
        {
          "source_ref": "29:38",
          "root": "ز ي ن",
          "source_word_indices": ["8"],
          "mapped_root_id": "root_000660",
          "branch_id": "B002",
          "variant_id": "V001",
          "role": "Presenting something as beautiful supports induced attractiveness rather than an assertion that the deeds were genuinely good."
        },
        {
          "source_ref": "29:38",
          "root": "ع م ل",
          "source_word_indices": ["11"],
          "mapped_root_id": "root_001046",
          "branch_id": "B001",
          "variant_id": "V001",
          "role": "Intentional acts, good or bad, remain their own deeds despite another agent's beautification."
        },
        {
          "source_ref": "29:38",
          "root": "ص د د",
          "source_word_indices": ["12"],
          "mapped_root_id": "root_000848",
          "branch_id": "B001",
          "variant_id": "V001",
          "role": "The transitive scope supplies diverting or preventing others from something."
        },
        {
          "source_ref": "29:38",
          "root": "س ب ل",
          "source_word_indices": ["14"],
          "mapped_root_id": "root_000672",
          "branch_id": "B001",
          "variant_id": "V001",
          "role": "A traversable route extended to a course or means supports the moral way."
        },
        {
          "source_ref": "29:38",
          "root": "ب ص ر",
          "source_word_indices": ["16"],
          "mapped_root_id": "root_000121",
          "branch_id": "B002",
          "variant_id": "V001",
          "role": "Inner sight, knowledge, and discernment support the concessive force of their being perceptive."
        }
      ],
      "structural_cues": [
        {
          "source_ref": "29:38",
          "quote_ar": "لَكُم",
          "role": "The evidence is addressed to the present audience."
        },
        {
          "source_ref": "29:38",
          "quote_ar": "لَهُمُ",
          "role": "The attractive appearance of the deeds belongs to the earlier people's perspective."
        },
        {
          "source_ref": "29:38",
          "quote_ar": "فَصَدَّهُمْ",
          "role": "The fa links diversion as a consequence of beautification."
        }
      ],
      "mechanism": "The ayah contrasts what is clear to its hearers with what looked attractive to the actors. The final circumstantial clause makes discernment coexist uneasily with diversion.",
      "changed_reading": null,
      "reader_inference": "The forms and inventories supply apparentness, habitation, beautification, intentional action, diversion, and discernment. Reading the final waw concessively is a grammatical interpretation; simple accompanying circumstance remains possible. The focus alone leaves the precise event inferred from the dwellings unstated.",
      "containment": "Preserve the ordinary historical and moral reading. Do not derive a history of ʿĀd from the root's return branches or infer specific buildings, routes, or punishments from this ayah alone."
    },
    {
      "model_id": "B2",
      "reading": "Their being 'discerning' can alternatively register confident conviction in the very conduct Satan had made attractive: felt clarity rather than reliable moral insight.",
      "status": "exploratory",
      "focus_anchor": {
        "quote_ar": "وَكَانُوا۟ مُسْتَبْصِرِينَ",
        "role": "The unqualified participle leaves the object and reliability of their insight unstated."
      },
      "activation_trace": [
        {
          "source_ref": "29:38",
          "root": "ب ص ر",
          "source_word_indices": ["16"],
          "mapped_root_id": "root_000121",
          "branch_id": "B002",
          "variant_id": "V001",
          "role": "The certainty and inward-knowledge scope permits considering a conviction-centered reading."
        },
        {
          "source_ref": "29:38",
          "root": "ز ي ن",
          "source_word_indices": ["8"],
          "mapped_root_id": "root_000660",
          "branch_id": "B002",
          "variant_id": "V001",
          "role": "Manufactured attractiveness provides a possible basis for misplaced confidence."
        }
      ],
      "structural_cues": [
        {
          "source_ref": "29:38",
          "quote_ar": "وَزَيَّنَ لَهُمُ ٱلشَّيْطَٰنُ أَعْمَٰلَهُمْ",
          "role": "The explicitly recipient-relative beautification makes subjective evaluation salient."
        }
      ],
      "mechanism": "The final description can be heard through the preceding account of manipulated evaluation: they acted with confidence while the narrator identified their course as diversion.",
      "changed_reading": null,
      "reader_inference": "The packet supplies certainty and beautification, not an explicit gloss 'imagined themselves rightly guided.' Assigning their certainty to the beautified deeds is reader-supplied. Genuine discernment culpably disregarded remains the stronger ordinary alternative.",
      "containment": "Present as a competing possibility, not a replacement translation or proof that the participle inherently means deluded."
    }
  ],
  "context_deltas": [
    {
      "model_id": "D1",
      "reading": "The attractive deeds and diversion can operate through socially persuasive alternatives to the right way, not only through an isolated individual's temptation.",
      "status": "supported",
      "focus_anchor": {
        "quote_ar": "وَزَيَّنَ لَهُمُ ٱلشَّيْطَٰنُ أَعْمَٰلَهُمْ فَصَدَّهُمْ عَنِ ٱلسَّبِيلِ",
        "role": "Collective recipients, their shared deeds, and the way allow a social mechanism of diversion."
      },
      "activation_trace": [],
      "structural_cues": [
        {
          "source_ref": "29:12",
          "quote_ar": "ٱتَّبِعُوا۟ سَبِيلَنَا وَلْنَحْمِلْ خَطَٰيَٰكُمْ",
          "role": "A rival way is marketed with a promise to absorb its moral cost."
        },
        {
          "source_ref": "29:12",
          "quote_ar": "إِنَّهُمْ لَكَٰذِبُونَ",
          "role": "The attractive reassurance is explicitly exposed as false."
        },
        {
          "source_ref": "29:25",
          "quote_ar": "أَوْثَٰنًۭا مَّوَدَّةَ بَيْنِكُمْ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا",
          "role": "Attachment to idols is connected with affection between people."
        },
        {
          "source_ref": "29:38",
          "quote_ar": "وَزَيَّنَ لَهُمُ ٱلشَّيْطَٰنُ أَعْمَٰلَهُمْ فَصَدَّهُمْ عَنِ ٱلسَّبِيلِ",
          "role": "Returns the persuasive social examples to beautification followed by diversion."
        }
      ],
      "mechanism": "The earlier invitation to 'our way' supplies a concrete persuasion pattern, and affection supplies a social reward. Together they make the focus's beautification intelligible as a process that may work through human relations.",
      "changed_reading": {
        "before": "Satanic beautification is stated without a social channel.",
        "after": "The window provides false reassurance and belonging as recognizable channels by which a wrong course becomes attractive."
      },
      "reader_inference": "These channels are explicit in their own contexts; applying them as possible mechanisms to the focus is analogical. Nothing identifies the speakers of 29:12 with ʿĀd or Thamūd or equates those speakers with Satan.",
      "containment": "Use the context to explain how beautification can work, not to invent the named peoples' institutions or specific conversations."
    },
    {
      "model_id": "D2",
      "reading": "The dwellings are evidence of a destructive outcome and an invitation to reason from surviving traces; the hearers must do with this evidence what the earlier people's discernment failed to secure.",
      "status": "supported",
      "focus_anchor": {
        "quote_ar": "وَقَد تَّبَيَّنَ لَكُم مِّن مَّسَٰكِنِهِمْ",
        "role": "The dwellings furnish the source from which something has become evident to the audience."
      },
      "activation_trace": [
        {
          "source_ref": "29:35",
          "root": "ت ر ك",
          "source_word_indices": ["2"],
          "mapped_root_id": "root_000180",
          "branch_id": "B002",
          "variant_id": "V001",
          "role": "Leaving an effect to remain supplies the model of a surviving trace."
        },
        {
          "source_ref": "29:35",
          "root": "ب ي ن",
          "source_word_indices": ["5"],
          "mapped_root_id": "root_000170",
          "branch_id": "B004",
          "variant_id": "V001",
          "role": "The clear sign anticipates the focus's becoming-clear construction."
        }
      ],
      "structural_cues": [
        {
          "source_ref": "29:35",
          "quote_ar": "وَلَقَد تَّرَكْنَا مِنْهَآ ءَايَةًۢ بَيِّنَةًۭ لِّقَوْمٍۢ يَعْقِلُونَ",
          "role": "A remnant is explicitly presented for reasoning."
        },
        {
          "source_ref": "29:37",
          "quote_ar": "فَكَذَّبُوهُ فَأَخَذَتْهُمُ ٱلرَّجْفَةُ فَأَصْبَحُوا۟ فِى دَارِهِمْ جَٰثِمِينَ",
          "role": "The immediate predecessor connects rejection, destruction, and residence."
        },
        {
          "source_ref": "29:38",
          "quote_ar": "وَعَادًۭا وَثَمُودَا۟ وَقَد تَّبَيَّنَ لَكُم مِّن مَّسَٰكِنِهِمْ",
          "role": "The coordinated names continue the historical sequence while turning its result into audience-facing evidence."
        },
        {
          "source_ref": "29:38",
          "quote_ar": "وَكَانُوا۟ مُسْتَبْصِرِينَ",
          "role": "Their discernment supplies the warning against treating access to evidence as sufficient."
        }
      ],
      "mechanism": "Sequence fills the focus's compressed reference to what became evident. The clear remnant for reasoning in 29:35 becomes a model for reading the named peoples' dwellings, while the shift from 'them' to 'you' transfers the interpretive responsibility.",
      "changed_reading": {
        "before": "The dwellings disclose an unspecified fact about the named peoples.",
        "after": "They disclose their destructive end as a reasoned warning addressed to a new audience."
      },
      "reader_inference": "The destructive sequence and trace-to-reasoning relation are supplied. Calling the dwellings surviving ruins is a reasonable contextual inference, not an archaeological description. The exact omitted governing verb for the coordinated names remains grammatically open.",
      "containment": "Do not identify a site, degree of preservation, or punishment mechanism for each people from these links."
    },
    {
      "model_id": "D3",
      "reading": "Satan's diversion does not absolve the people: their perceptiveness and their own deeds belong to a sequence in which clear evidence can be met with pride and punishment is attributed to the actors' wrongdoing.",
      "status": "supported",
      "focus_anchor": {
        "quote_ar": "أَعْمَٰلَهُمْ فَصَدَّهُمْ عَنِ ٱلسَّبِيلِ وَكَانُوا۟ مُسْتَبْصِرِينَ",
        "role": "Their ownership of the deeds and their discernment coexist with Satan's causal agency."
      },
      "activation_trace": [],
      "structural_cues": [
        {
          "source_ref": "29:38",
          "quote_ar": "أَعْمَٰلَهُمْ فَصَدَّهُمْ عَنِ ٱلسَّبِيلِ وَكَانُوا۟ مُسْتَبْصِرِينَ",
          "role": "Focus endpoint of the agency and responsibility relation."
        },
        {
          "source_ref": "29:39",
          "quote_ar": "وَلَقَدْ جَآءَهُم مُّوسَىٰ بِٱلْبَيِّنَٰتِ فَٱسْتَكْبَرُوا۟ فِى ٱلْأَرْضِ",
          "role": "The next example explicitly juxtaposes clear evidence and arrogant response."
        },
        {
          "source_ref": "29:40",
          "quote_ar": "فَكُلًّا أَخَذْنَا بِذَنۢبِهِۦ",
          "role": "The retrospective summary attributes seizure to each one's sin."
        },
        {
          "source_ref": "29:40",
          "quote_ar": "وَمَا كَانَ ٱللَّهُ لِيَظْلِمَهُمْ وَلَٰكِن كَانُوٓا۟ أَنفُسَهُمْ يَظْلِمُونَ",
          "role": "The summary expressly locates wrongdoing in the actors rather than divine injustice."
        }
      ],
      "mechanism": "The following parallel and collective summary constrain the focus's causal account: an external tempter and accountable human action are simultaneous explanatory levels.",
      "changed_reading": {
        "before": "Satan's active role might dominate the explanation of their deviation.",
        "after": "The sequence explicitly preserves their culpability and makes unused discernment aggravating rather than exculpatory."
      },
      "reader_inference": "The summary supplies culpability without an additional causal assumption. Pride is explicit for the next group; extending that exact motive to every member of ʿĀd and Thamūd would exceed the evidence.",
      "containment": "Retain both agencies without constructing a complete theory of free will or transferring every feature of the following example to the focus."
    },
    {
      "model_id": "D4",
      "reading": "The dwellings can also be read as failed assurances of security: material habitation remains visible after its occupants are gone, whereas neither an adopted protector nor a house guarantees preservation.",
      "status": "exploratory",
      "focus_anchor": {
        "quote_ar": "مِّن مَّسَٰكِنِهِمْ",
        "role": "Concrete habitation carries an analogy between having a dwelling and possessing effective shelter."
      },
      "activation_trace": [
        {
          "source_ref": "29:38",
          "root": "س ك ن",
          "source_word_indices": ["7"],
          "mapped_root_id": "root_000726",
          "branch_id": "B004",
          "variant_id": "V001",
          "role": "The scope includes a house as something in which one finds rest and comfort."
        },
        {
          "source_ref": "29:41",
          "root": "ب ي ت",
          "source_word_indices": ["11", "14", "15"],
          "mapped_root_id": "root_000166",
          "branch_id": "B001",
          "variant_id": "V001",
          "role": "The same shelter-and-dwelling scope explicitly includes the spider's house."
        }
      ],
      "structural_cues": [
        {
          "source_ref": "29:38",
          "quote_ar": "وَقَد تَّبَيَّنَ لَكُم مِّن مَّسَٰكِنِهِمْ",
          "role": "Their habitations become evidence for others rather than continuing security for them."
        },
        {
          "source_ref": "29:41",
          "quote_ar": "مَثَلُ ٱلَّذِينَ ٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ أَوْلِيَآءَ كَمَثَلِ ٱلْعَنكَبُوتِ ٱتَّخَذَتْ بَيْتًۭا",
          "role": "The subsequent parable compares adopted protectors with a constructed house."
        },
        {
          "source_ref": "29:41",
          "quote_ar": "وَإِنَّ أَوْهَنَ ٱلْبُيُوتِ لَبَيْتُ ٱلْعَنكَبُوتِ",
          "role": "Possessing a house is distinguished from possessing effective protection."
        },
        {
          "source_ref": "29:58",
          "quote_ar": "لَنُبَوِّئَنَّهُم مِّنَ ٱلْجَنَّةِ غُرَفًۭا",
          "role": "Later divine lodging supplies a contrasting positive habitation."
        },
        {
          "source_ref": "29:58",
          "quote_ar": "خَٰلِدِينَ فِيهَا",
          "role": "The promised dwelling is paired with enduring occupancy."
        }
      ],
      "mechanism": "The repeated habitation field shifts attention from buildings as historical evidence to the difference between apparent shelter and secure dwelling. The later promise prevents this from becoming a blanket rejection of habitation.",
      "changed_reading": {
        "before": "Dwellings are the material source of knowledge about the past.",
        "after": "They additionally exemplify habitation whose apparent security did not preserve its people, contrasted with promised enduring lodging."
      },
      "reader_inference": "The packet supplies dwellings, the weak-house parable, and enduring lodging. That the earlier peoples trusted their buildings as guarantees is not stated; the security reading is a literary analogy, not a recovered motive.",
      "containment": "Qualify as a resonance. Do not claim their houses were physically flimsy or that the spider parable directly names these peoples."
    },
    {
      "model_id": "D5",
      "reading": "Diversion is morally directional, not merely an act of restraint: Satan keeps people from the way, while prayer keeps people from indecency and wrongdoing.",
      "status": "supported",
      "focus_anchor": {
        "quote_ar": "فَصَدَّهُمْ عَنِ ٱلسَّبِيلِ",
        "role": "The complement after 'away from' identifies what harmful restraint excludes."
      },
      "activation_trace": [],
      "structural_cues": [
        {
          "source_ref": "29:38",
          "quote_ar": "فَصَدَّهُمْ عَنِ ٱلسَّبِيلِ",
          "role": "Restraint directed away from the right course."
        },
        {
          "source_ref": "29:45",
          "quote_ar": "إِنَّ ٱلصَّلَوٰةَ تَنْهَىٰ عَنِ ٱلْفَحْشَآءِ وَٱلْمُنكَرِ",
          "role": "A parallel restraint-plus-'from' construction has the opposite moral object."
        }
      ],
      "mechanism": "The shared relational construction exposes a reversal: being kept away is harmful or beneficial according to what one is kept away from. The focus describes a misdirected regulation of conduct, not the mere absence of regulation.",
      "changed_reading": {
        "before": "The focus describes a negative obstruction.",
        "after": "Its obstruction is contrasted with a positive restraint that redirects action away from the very kinds of wrong beautification can disguise."
      },
      "reader_inference": "The two constructions and opposite objects are explicit. Treating prayer as the literary counterpattern needs no claim that this ayah prescribes a specific cure for the historical peoples.",
      "containment": "Do not identify ṣadd and nahy as interchangeable lexemes or infer an automatic psychological effect for every performance of prayer."
    },
    {
      "model_id": "D6",
      "reading": "Their discernment need not mean comprehensive right judgment: recognition of truth can coexist with denial, misdirection, and a failure to draw its practical implications.",
      "status": "supported",
      "focus_anchor": {
        "quote_ar": "وَكَانُوا۟ مُسْتَبْصِرِينَ",
        "role": "The final clause affirms a perceptual or cognitive capacity without specifying its whole domain."
      },
      "activation_trace": [
        {
          "source_ref": "29:49",
          "root": "ج ح د",
          "source_word_indices": ["11"],
          "mapped_root_id": "root_000224",
          "branch_id": "B001",
          "variant_id": "V001",
          "role": "Knowing denial supplies an explicit lexical model of recognition without acknowledgment."
        }
      ],
      "structural_cues": [
        {
          "source_ref": "29:38",
          "quote_ar": "فَصَدَّهُمْ عَنِ ٱلسَّبِيلِ وَكَانُوا۟ مُسْتَبْصِرِينَ",
          "role": "The focus's juxtaposition is the apparent cognitive tension being explained."
        },
        {
          "source_ref": "29:49",
          "quote_ar": "وَمَا يَجْحَدُ بِـَٔايَٰتِنَآ إِلَّا ٱلظَّٰلِمُونَ",
          "role": "Denial of signs is morally characterized."
        },
        {
          "source_ref": "29:61",
          "quote_ar": "لَيَقُولُنَّ ٱللَّهُ ۖ فَأَنَّىٰ يُؤْفَكُونَ",
          "role": "An acknowledged divine answer is immediately juxtaposed with being turned away."
        },
        {
          "source_ref": "29:63",
          "quote_ar": "لَيَقُولُنَّ ٱللَّهُ",
          "role": "A second acknowledgment confirms that some knowledge is present."
        },
        {
          "source_ref": "29:63",
          "quote_ar": "بَلْ أَكْثَرُهُمْ لَا يَعْقِلُونَ",
          "role": "Acknowledgment nevertheless fails to become adequate reasoning."
        }
      ],
      "mechanism": "The later question-and-answer pattern demonstrates selective cognition in action. It makes the focus's coexistence of insight and diversion intelligible without reducing insight either to physical eyesight or to full moral correctness.",
      "changed_reading": {
        "before": "Discernment appears to conflict with their being diverted.",
        "after": "Discernment can be real but partial, unacted upon, or contradicted by acknowledgment and conduct."
      },
      "reader_inference": "The contexts supply knowing denial and explicit acknowledgment alongside misdirection. They do not specify exactly what ʿĀd and Thamūd knew. Genuine insight disregarded, practical competence without sound religious judgment, and the exploratory confidence reading remain distinct alternatives.",
      "containment": "Use the contexts to delimit what discernment guarantees, not to attribute their exact answers or knowledge to the earlier peoples."
    },
    {
      "model_id": "D7",
      "reading": "The obstructed way is set against God's promised ways for those who strive toward Him: the focus's failed discernment is not a claim that guidance is inaccessible.",
      "status": "supported",
      "focus_anchor": {
        "quote_ar": "فَصَدَّهُمْ عَنِ ٱلسَّبِيلِ",
        "role": "The denied course is the negative endpoint of a guidance contrast."
      },
      "activation_trace": [],
      "structural_cues": [
        {
          "source_ref": "29:38",
          "quote_ar": "فَصَدَّهُمْ عَنِ ٱلسَّبِيلِ",
          "role": "Satan's agency leads away from the way."
        },
        {
          "source_ref": "29:69",
          "quote_ar": "وَٱلَّذِينَ جَٰهَدُوا۟ فِينَا لَنَهْدِيَنَّهُمْ سُبُلَنَا",
          "role": "God promises guidance into His ways to those whose striving is directed toward Him."
